mapper.select:
SELECT 
	FROM FIN_BASE_RULE_INFO
	WHERE FINPROD_ID   = #{finprodId}
	AND BRANCH         = #{branchId}
	AND BASE_RULE_TYPE = '${BASE_RULE_TYPE_01}'
	AND EFF_DATE       =
	  (SELECT MAX(EFF_DATE)
		  FROM FIN_BASE_RULE_INFO
		  WHERE FINPROD_ID   = #{finprodId}
			    AND BRANCH         = #{branchId}
			    AND BASE_RULE_TYPE = '${BASE_RULE_TYPE_01}'
			    AND EFF_DATE   <= #{effDate,jdbcType=DATE}
	  )
